def transform(grid):
    h, w = len(grid), len(grid[0])
    wall = next(r for r, row in enumerate(grid) if row and all(x == 2 for x in row))
    out = [[0] * w for _ in range(h)]
    for r, row in enumerate(grid):
        for c, v in enumerate(row):
            if v == 2:
                out[r][c] = 2
            elif v == 4:
                if r < wall:
                    center = (r + 1, c)
                    out[center[0]][center[1]] = 4
                    for d in range(1, h):
                        rr = center[0] - d
                        if rr < 0:
                            break
                        for cc in (c-d, c+d):
                            if 0 <= cc < w:
                                out[rr][cc] = 4
                else:
                    out[r][c] = 4
    return out
